notice('facebook-checkpoint-disabled-link-explained','fb','facebook.com/checkpoint/disabled: What That Link Means (2026)','Facebook checkpoint link',
 'Seeing facebook.com/checkpoint or /checkpoint/disabled when you log in? What a Facebook checkpoint is, what “disabled” in the link means and what to do.',
 'facebook.com/checkpoint/disabled, explained.','What the checkpoint page means and which step comes next.',
 '<strong>A Facebook “checkpoint” is the screen Facebook shows when it stops a login until you complete a step. A link containing /checkpoint/disabled means the profile is disabled or suspended, and the appeal or identity step starts on that screen.</strong> Do not share the link as your “profile link”: it does not identify your account. Send your profile name or old profile URL instead. If the checkpoint leads to a rejected appeal, Unbanz takes Facebook cases for $900, paid upfront with a 100% refund if it fails.',
 [('Checkpoint','A blocking step at login.'),('/disabled','The profile is disabled or suspended.'),('Not a profile link','It does not identify you.')],
 [('types','Common checkpoint screens',table([('We suspended your account','Appeal within the window shown.'),('Confirm your identity','Upload ID or a video selfie in the flow.'),('Your account has been locked','Unlock with the steps shown.'),('We received your information','Wait; the review is pending.')],('Screen','What it means'))),
  ('profile','How to find your real profile link',ol(['Ask a friend to open your profile and copy the link.','Look in old emails from Facebook for your profile name.','Check a Page you admin for your name in its admin list.']))],
 [('Why does the link show my IP or a long code?','It is session data, not account information. Do not post it publicly.'),('Can someone else use my checkpoint link?','It is tied to your session, but treat it as private.')],
 [('/facebook-we-suspended-your-account-notice/','We suspended your account'),('/facebook-your-account-has-been-locked-notice/','Your account has been locked')],FBL+HK[1:])
notice('instagram-weve-restricted-your-account-notice','ig','Instagram “We’ve Restricted Your Account”: What It Means (2026)','Instagram restricted your account',
 'Instagram says “We’ve restricted your account” or limits likes, follows or comments? What a restriction is, how long it lasts and when to appeal.',
 '“We’ve restricted your account” on Instagram.','How a restriction differs from a suspension, and what to do.',
 '<strong>A restriction limits features, such as following, liking, commenting, messaging or going live, without disabling the account.</strong> It usually comes with an end date in Account Status. Stop the activity that triggered it, remove automation apps, and use Request a review in Account Status if it is offered. If the restriction turns into “We suspended your account”, appeal from that notice. Unbanz handles disabled and suspended Instagram accounts for $800, paid upfront with a 100% refund if it fails.',
 [('Features limited','The account still works.'),('End date','Shown in Account Status.'),('Stop the trigger','Pause the activity.')],
 [('vs','Restricted vs suspended vs disabled',table([('Restricted','Some features blocked for a time'),('Suspended','You cannot use the account; appeal window shown'),('Disabled','Appeal rejected or window passed')],('Notice','What it means'))),
  ('do','What to do',ol(['Open Settings, then Account Status.','Read which feature is limited and until when.','Remove third-party apps.','Request a review only if offered.']))],
 [('How long does an Instagram restriction last?','Often days or a few weeks; Account Status shows the date.'),('Will appealing make it longer?','No, but repeated appeals do not speed it up.')],
 [('/instagram-account-disabled-vs-suspended-vs-restricted/','Disabled vs suspended vs restricted'),('/instagram-we-limit-how-often-notice/','We limit how often')],IGL)
notice('facebook-confirm-you-are-human-notice','fb','Facebook “Confirm You’re Human”: How to Get Past It (2026)','Facebook confirm you’re human',
 'Facebook asks you to confirm you’re human and keeps looping? What the check is, how to complete it safely and when it turns into a suspension.',
 'Facebook asks you to confirm you’re human.','How to get through the check without making it worse.',
 '<strong>Facebook shows a “confirm you’re human” check when activity looks automated, for example many friend requests, messages or logins in a short time.</strong> Complete the captcha or phone step in the official flow, on your usual device and network, without a VPN. If it loops, wait 24 hours before trying again. If it ends in “We suspended your account”, appeal from that notice. Unbanz handles suspended Facebook profiles for $900, paid upfront with a 100% refund if it fails.',
 [('Anti-bot check','Triggered by bursts of activity.'),('Usual device','No VPN.'),('Loops','Wait, then retry once.')],
 [('steps','How to complete it',ol(['Use the app or browser you normally use.','Turn off any VPN or proxy.','Complete the captcha or code step.','If it fails, wait a day before trying again.'])),
  ('loop','If it keeps looping',ul(['Update the app, or try a browser.','Do not create a new account.','If you are then suspended, see '+a('/facebook-we-suspended-your-account-notice/','we suspended your account')+'.']))],
 [('Is “confirm you’re human” a ban?','No. It becomes one only if the account is then suspended.'),('Should I give my phone number?','Only inside Facebook’s own flow.')],
 [('/instagram-confirm-you-are-human-loop/','Instagram confirm you’re human'),('/facebook-we-suspended-your-account-notice/','We suspended your account')],FBL)
notice('facebook-personal-advertising-access-restricted','ad','Facebook Profile “Restricted from Advertising”: Personal Ad Access (2026)','Profile advertising restricted',
 'Your Facebook profile is restricted from advertising, even though your profile and Page work? What a personal advertising restriction is and how to get it reviewed. $1,200.',
 'Your profile is restricted from advertising.','When the restriction is on you, not the ad account or Page.',
 '<strong>A personal advertising restriction sits on your Facebook profile: you cannot run or manage ads in any ad account, even though your profile and Pages still work.</strong> Check it in Business Support Home or Account Quality, and use Request review there if the button is shown. If there is no button, or the review was rejected, Unbanz handles Instagram and Facebook ad account restrictions, including personal advertising access, for a fixed $1,200, paid upfront with a 100% refund if it fails.',
 [('On your profile','Not the ad account.'),('All ad accounts','You cannot advertise anywhere.'),('$1,200','Fixed fee if you want help.')],
 [('tell','How to tell it is personal',ul(['Every ad account you join shows you as unable to advertise.','Business Support Home lists the restriction under your profile.','Other admins can still run ads in the same ad account.'])),
  ('do','What to do',ol(['Open Business Support Home and find the restriction on your profile.','Use Request review if offered, and complete identity checks there.','Let another admin keep campaigns running meanwhile.','Do not create a second profile to advertise.'])),
  ('old','If the restriction is old','<p>Restrictions from years ago often show no review button. That does not always mean nothing can be done, but the free route is closed.</p>')],
 [('Can my business still advertise?','Yes, if another admin without a restriction runs the ads.'),('Is this the same as a disabled ad account?','No. See '+a('/meta-ad-account-restricted-vs-disabled-personal-profile/','restricted vs disabled')+'.')],
 [('/ad-account-recovery/','Ad account recovery'),('/meta-ad-account-appeal-links-directory/','Ad account appeal links')],[BSH])
notice('instagram-disabled-fraud-and-deception','ig','Instagram Disabled for “Fraud and Deception”: What to Do (2026)','Instagram fraud and deception',
 'Instagram disabled your account for fraud and deception and rejected the appeal? What the policy covers, typical false flags for small sellers, and what can still be done.',
 'Instagram disabled for fraud and deception.','Common for small shops and gift sellers, and sometimes a mistake.',
 '<strong>Meta’s fraud, scams and deceptive practices policy covers things like selling goods that never arrive, fake giveaways, misleading offers and impersonation.</strong> Small sellers are sometimes caught by reports from unhappy buyers or competitors. Appeal from the notice with proof of real orders, delivery and your business identity. If the appeal is rejected and you can no longer request a review, Unbanz handles Instagram cases for $800, paid upfront with a 100% refund if it fails.',
 [('Seller accounts','Often hit by reports.'),('Proof','Orders, delivery, business details.'),('One appeal','Clear and factual.')],
 [('proof','Proof that helps',ul(['Order confirmations and tracking numbers.','A website or registered business name.','Messages showing customers received items.'])),
  ('avoid','Things that make it worse',ul(['New accounts selling the same products.','Giveaways asking people to pay a fee.','Using customers’ photos without permission.']))],
 [('Can a fraud flag be removed?','Sometimes, with proof the business is real.'),('Will my followers come back?','If the account is restored, yes.')],
 [('/instagram-suspended-scam-or-fraud-flag/','Scam or fraud flag'),('/you-cant-request-another-review-instagram-facebook/','Can’t request another review')],IGL+[CS])
notice('facebook-suspended-because-of-linked-account','fb','Facebook Suspended Because of a Linked Instagram or Threads Account (2026)','Facebook suspended because of linked account',
 'Facebook suspended your profile because of a linked Instagram or Threads account? How Accounts Center links them and which account to appeal first.',
 'Facebook suspended because of a linked account.','When Instagram or Threads brings your Facebook profile down with it.',
 '<strong>When accounts share an Accounts Center, a decision on one can spread to the others.</strong> Find the account that was disabled first: that is usually the one to appeal. Appeal each account that shows its own notice, and say in each appeal which account started it. If Facebook says you can’t request another review, Unbanz handles Facebook cases for $900 and Instagram for $800, paid upfront with a 100% refund if it fails.',
 [('Accounts Center','How accounts get linked.'),('Find the first','Appeal the source first.'),('Each notice','Appeal every one shown.')],
 [('order','Which account to appeal first',ol(['Check which account was disabled first (look at the dates in emails).','Appeal that one from its own notice.','Then appeal the linked account and mention the first one.'])),
  ('threads','Threads','<p>Threads profiles sit on top of Instagram, so an Instagram disable usually takes Threads with it. See '+a('/threads-suspended-but-instagram-works/','Threads suspended')+'.</p>')],
 [('Can I unlink accounts after a suspension?','Not while they are suspended, and unlinking does not reverse the decision.'),('Do I need to appeal both?','Yes, if both show their own notice.')],
 [('/facebook-and-instagram-disabled-together-linked-accounts/','Disabled together'),('/instagram-suspended-linked-to-account-you-dont-own/','Linked to an account you do not own')],FBL+IGL)
notice('instagram-suspended-linked-to-account-you-dont-own','ig','Instagram Suspended for a Linked Account You Don’t Own (2026)','Linked to an account you don’t own',
 'Instagram says your account is linked to another account that broke the rules, but you don’t own it? Why it happens and how to appeal.',
 'Suspended for an account you don’t own.','When Instagram links you to a stranger’s account.',
 '<strong>Instagram can link accounts through a shared device, phone number, email, Wi-Fi network or a login it saw.</strong> If one account breaks the rules, linked accounts can be suspended too, even if you never owned it. Appeal from your own notice, name the other account, say you do not own or control it, and explain any shared device or network. If the appeal fails, Unbanz handles Instagram cases for $800, paid upfront with a 100% refund if it fails.',
 [('Shared signals','Device, phone, Wi-Fi.'),('Name it','Say which account and that it is not yours.'),('Secure yours','Change password and 2FA.')],
 [('how','How a stranger gets linked',ul(['You logged in on a friend’s or shop’s phone.','A hacker logged into your account from their device.','You share a network with many people, such as a dorm.','Your email or phone was added to their account.'])),
  ('write','What to write',ol(['Your username and that you own it.','The other username and that you do not own or control it.','Any shared device, network or past hack.','A request for a human review.']))],
 [('Can I prove I don’t own the other account?','You can explain it; Meta checks its own signals.'),('Should I report the other account?','Yes, if it is impersonating you.')],
 [('/instagram-disabled-because-of-a-linked-account/','Disabled because of a linked account'),('/facebook-suspended-because-of-linked-account/','Facebook suspended because of linked account')],IGL)
notice('instagram-disabled-intellectual-property-violations','ig','Instagram Disabled for Intellectual Property Violations (2026)','Instagram IP violations',
 'Instagram disabled your account for repeated intellectual property (copyright or trademark) violations? How repeat-infringer disables work and the counter-notice route.',
 'Instagram disabled for intellectual property violations.','Repeat copyright or trademark reports, and what you can still do.',
 '<strong>Instagram disables accounts that receive repeated copyright or trademark reports.</strong> Unlike most policy disables, the key fix is often the reports themselves: if a report was wrong, you can respond through Meta’s IP process, and a rights holder can withdraw a report. Appeal from the notice as well, and list the content you believe was reported unfairly. If that fails, Unbanz handles Instagram cases for $800, paid upfront with a 100% refund if it fails.',
 [('Repeat reports','The usual cause.'),('Counter-notice','For wrong reports.'),('Withdrawals','The reporter can retract.')],
 [('do','What to do',ol(['Check the emails from Instagram for each report and who filed it.','If a report is wrong, respond through Meta’s intellectual property process.','If you know the reporter, ask them to withdraw it.','Appeal the disable from the notice.']))],
 [('Do copyright strikes expire on Instagram?','Meta does not publish a fixed expiry.'),('Can music in Reels cause this?','Repeated reports on music can contribute.')],
 [('/facebook-reels-copyright-strike-what-to-do/','Reels copyright strike'),('/instagram-trademark-report-rejected-username/','Trademark report')],IGL+[('Meta intellectual property help','https://www.facebook.com/help/intellectual_property','Meta’s copyright and trademark help, including reporting and responding.')])
notice('meta-manual-human-review-request','ig','How to Request a Manual Human Review from Meta (2026)','Request a human review',
 'Want a real person at Meta to review your disabled Instagram or Facebook account? Where a human review actually happens, what to write and what does not work.',
 'How to ask Meta for a human review.','Where human review happens, and what does not reach it.',
 '<strong>There is no form or email that guarantees a human at Meta reads your case.</strong> Human review happens inside Meta’s own appeal: from the notice, from Account Status, through Meta Verified chat for subscribers, or in Business Support Home for advertisers. Letters sent to random Meta email addresses are not read as appeals. Ask for a human review inside the appeal you submit. If that fails, Unbanz handles Instagram ($800) and Facebook ($900) cases, paid upfront with a 100% refund if it fails.',
 [('Inside the appeal','That is where it happens.'),('No magic email','Letters elsewhere are not read.'),('Meta Verified','Chat, not a guarantee.')],
 [('where','Where a review can happen',table([('In-app appeal','Everyone with a notice'),('Account Status, Request a review','If you can log in'),('Meta Verified chat','Subscribers'),('Business Support Home','Advertisers and Page admins')],('Route','Who'))),
  ('letter','A short appeal that asks for review',ol(['Who you are and your username.','What the notice says.','Why you think it is a mistake.','“Please have a person review this decision.”']))],
 [('Can I call Meta for a human review?','No. Meta has no public phone line for accounts.'),('Do emails to Meta work?','Not as appeals. See '+a('/i-sent-an-appeal-letter-to-meta-by-email/','sent an appeal by email')+'.')],
 [('/how-to-contact-meta-about-a-disabled-account/','How to contact Meta'),('/meta-verified-support-how-to-use/','Meta Verified support')],IGL+FBL)
